import * as THREE from 'three';

/**
 * Wie weit der Boden reicht — und damit, wie weit man laufen kann.
 *
 * Jede Welt stand vorher auf ihrer eigenen kleinen Platte, und an deren Rand
 * war die Welt zu Ende: ein Schritt zu weit und man fiel ins Nichts. Eine
 * Sandkiste, die man nicht verlassen kann, ist aber genau das Gegenteil von
 * einer Sandkiste. Also liegt unter *jeder* Welt eine Fläche, die bis an den
 * Horizont geht — man kann jederzeit rausgehen, sich die Welt von außen
 * ansehen und wieder zurückkommen.
 *
 * Die Zahl ist die halbe Kantenlänge in Metern und hängt an der Sichtweite der
 * Kamera: weiter zu bauen als man sieht, kostet nur Dreiecke.
 */
export const WORLD_RADIUS = 500;

/** Der Himmel steht außen herum — und damit immer hinter dem Boden. */
export const SKY_RADIUS = 560;

/**
 * Wo die **Oberseite** des Bodens liegt: eine Handbreit unter der Null.
 *
 * Die gebauten Böden der Welten liegen auf `y = 0`, und zwei Flächen auf
 * derselben Höhe flimmern gegeneinander.
 */
export const GROUND_TOP = -0.05;

/**
 * Wie **dick** die Bodenplatte ist.
 *
 * Zu sehen ist davon nichts — man steht darauf, nicht daneben —, und trotzdem
 * ist es die wichtigste Zahl in dieser Datei. Der Boden war vorher eine
 * `PlaneGeometry`, also ein Ding *ohne* Dicke, und der Collider dazu kommt aus
 * der Bounding-Box: aus null wurde ein Zentimeter, das Minimum. Ein Zentimeter
 * ist aber **dünner als die Haut des Character-Controllers** (`0.02`, siehe
 * `PhysicsLocomotion`) — die Kapsel steckte damit dauernd halb im Boden, und
 * ein Controller, der eine Durchdringung auflösen muss, gibt in dieser Frame
 * keine Bewegung heraus. Genau so sah es aus: ein paar Schritte, ein Stocken,
 * ein paar Schritte, und dabei sank man langsam ein.
 *
 * Ein halber Meter ist bequem mehr als jede Toleranz und immer noch dünn genug,
 * dass ein Bodenportal einen hindurchfallen lässt.
 */
export const GROUND_THICKNESS = 0.6;

/**
 * **Kulisse**: etwas, das hinter der Welt steht und nicht zu ihr gehört — der
 * Himmel, die Fläche bis zum Horizont, die Sterne, die Erde über dem Mond.
 *
 * Im Spiel ist die Marke folgenlos; wer sie liest, ist die Werkzeugseite. Dort
 * wird eine Welt eingepasst wie ein Werkzeug, und eine Himmelskugel von 560
 * Metern um ein Haus von neun machte aus dem Haus einen Punkt in der Mitte.
 * Gezeichnet wird die Kulisse trotzdem: hinter der Welt gehört sie hin.
 */
export function markBackdrop<T extends THREE.Object3D>(object: T): T {
  object.userData.backdrop = true;
  return object;
}

/** Cheap gradient sky as an inverted sphere — no HDRI download needed. */
export function createSky(top: number, bottom: number, radius = SKY_RADIUS): THREE.Mesh {
  const material = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      topColor: { value: new THREE.Color(top) },
      bottomColor: { value: new THREE.Color(bottom) },
    },
    vertexShader: /* glsl */ `
      varying vec3 vWorldPosition;
      void main() {
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorldPosition = world.xyz;
        gl_Position = projectionMatrix * viewMatrix * world;
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 topColor;
      uniform vec3 bottomColor;
      varying vec3 vWorldPosition;
      void main() {
        float h = clamp(normalize(vWorldPosition).y * 0.5 + 0.5, 0.0, 1.0);
        gl_FragColor = vec4(mix(bottomColor, topColor, pow(h, 0.8)), 1.0);
      }
    `,
  });
  const sky = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 16), material);
  sky.name = 'sky';
  sky.frustumCulled = false;
  return markBackdrop(sky);
}

export function createLighting(intensity = 1): THREE.Group {
  const group = new THREE.Group();
  group.name = 'lighting';

  const hemi = new THREE.HemisphereLight(0xbdd7ff, 0x2a3142, 1.5 * intensity);
  group.add(hemi);

  const key = new THREE.DirectionalLight(0xffffff, 1.6 * intensity);
  key.position.set(4, 8, 3);
  group.add(key);

  const fill = new THREE.DirectionalLight(0x6a9bff, 0.5 * intensity);
  fill.position.set(-5, 3, -4);
  group.add(fill);

  return group;
}

/**
 * **Nur die Formen wegräumen, die Materialien behalten.**
 *
 * Für alles, was **umgebaut** statt verlassen wird: eine Gitterwelt, an der
 * man im Stehen weiterbaut (`grid/GridWorld.ts`), die Miniatur des Editors.
 * Dort teilen sich hundert Quader acht Materialien — und wer beim Umbauen
 * `disposeTree` nimmt, gibt dieselben acht hundertmal frei und lädt sie im
 * nächsten Bild wieder hoch. Die Geometrie dagegen gehört jedem Quader
 * allein, und sie muss weg.
 *
 * **Außer dort, wo `userData.sharedAssets` steht** — dieselbe Ausnahme und
 * derselbe Grund wie bei `disposeTree` weiter unten, nur hier leichter zu
 * übersehen: „Gehört jedem Quader allein" gilt für Quader, die diese Welt
 * selbst gebaut hat, und nicht für die Kopie eines Modells aus dem Regal
 * (`core/kaykitModel.ts`). Deren Puffer gehört der Vorlage im Speicher und
 * allen anderen Kopien; wer ihn beim **Umbauen** freigibt, nimmt ihn allen
 * weg — und die Gitterwelt baut bei jeder Änderung um
 * (`grid/GridWorld.ts`, `rebuildFixtures`). Die Druckplatte
 * (`grid/fixtures/plate.ts`) hängt genau so ein Modell in ihren Einbau, und
 * ohne diese Zeile wäre sie nach dem ersten Umbau eine Platte aus nichts.
 *
 * Eine eigene Rekursion statt `traverse`, und zwar aus demselben Grund wie
 * dort: Ein `return` in einem `traverse` überspringt den Knoten und **nicht**
 * seine Kinder — und die Netze hängen gerade unter dem markierten Knoten.
 */
export function disposeShapes(root: THREE.Object3D): void {
  dropShapes(root);
  root.removeFromParent();
}

function dropShapes(object: THREE.Object3D): void {
  if ((object.userData as { sharedAssets?: boolean }).sharedAssets) return;
  (object as Partial<THREE.Mesh>).geometry?.dispose();
  for (const child of object.children) dropShapes(child);
}

/**
 * Disposes every geometry/material below `root` and detaches it.
 *
 * **Außer dort, wo `userData.sharedAssets` steht** — dann endet das Aufräumen
 * an diesem Knoten, und alles darunter bleibt, wie es ist.
 *
 * Das ist die Ausnahme für alles, was sich seine Geometrie mit anderen teilt.
 * Ein Modell aus dem Asset-Regal ist die Kopie einer Vorlage, die im Speicher
 * liegen bleibt (`core/kaykitModel.ts`): Sie teilen sich den Puffer, und wer
 * ihn beim Wegräumen **eines** Fasses freigibt, nimmt ihn allen anderen weg —
 * auch der Vorlage, aus der das nächste gebaut würde. In der Brille steht
 * danach ein Fass, das aus nichts besteht, und niemand sucht das in einer
 * Aufräumfunktion.
 *
 * Deshalb eine eigene Rekursion statt `traverse`: Ein `return` in einem
 * `traverse` überspringt nur den Knoten selbst, nicht seine Kinder — und die
 * Netze hängen gerade unter dem markierten Knoten.
 */
export function disposeTree(root: THREE.Object3D): void {
  dropResources(root);
  root.removeFromParent();
}

function dropResources(object: THREE.Object3D): void {
  if ((object.userData as { sharedAssets?: boolean }).sharedAssets) return;
  const mesh = object as Partial<THREE.Mesh> & THREE.Object3D;
  mesh.geometry?.dispose();
  const material = mesh.material;
  if (Array.isArray(material)) material.forEach((m) => m.dispose());
  else material?.dispose();
  for (const child of object.children) dropResources(child);
}

/**
 * Der Boden unter allem: eine Fläche bis zum Horizont, mit einem Raster, an
 * dem man sieht, dass man sich bewegt.
 *
 * Ohne Struktur ist eine große einfarbige Ebene in der Brille nicht von Nebel
 * zu unterscheiden — man läuft und nichts passiert. Das Raster ist deshalb
 * kein Zierrat, sondern das, was aus der Fläche einen Ort macht. Es wird als
 * Textur gekachelt statt als Geometrie gezeichnet: ein `GridHelper` über einen
 * Kilometer wären hunderttausend Linien.
 */
export function createGround(
  color: number,
  options: { line?: number; radius?: number; tile?: number; checker?: number } = {},
): THREE.Mesh {
  const radius = options.radius ?? WORLD_RADIUS;
  // **Ein Meter je Feld**, und die Zeichenfläche trägt zwei mal zwei davon:
  // Ein Schachbrett braucht vier Felder, damit sich das Muster beim Kacheln
  // fortsetzt. Vorher waren es vier Meter je Kachel und ein einzelnes Feld
  // darin — draußen stand damit ein Raster, das mit dem Metergitter, auf dem
  // gebaut wird (`worlds/grid/`), nichts zu tun hatte.
  const tile = options.tile ?? CHECKER_TILE * 2;
  const texture = checkerTexture(color, options.line ?? 0x000000, options.checker ?? mixed(color));
  texture.repeat.set((radius * 2) / tile, (radius * 2) / tile);

  // Ein **Kasten** und keine Ebene: der Collider kommt aus der Geometrie, und
  // eine Ebene hat keine Dicke (siehe `GROUND_THICKNESS`). Sechs Flächen statt
  // zweier Dreiecken kosten nichts; was sie einbringen, ist ein Boden, auf dem
  // man wirklich gehen kann.
  const ground = new THREE.Mesh(
    new THREE.BoxGeometry(radius * 2, GROUND_THICKNESS, radius * 2),
    new THREE.MeshStandardMaterial({ map: texture, roughness: 0.95, metalness: 0.02 }),
  );
  ground.name = 'ground';
  // Gemessen wird an der Oberseite: die soll dort liegen, wo vorher die Ebene
  // lag, sonst wandert mit der Dicke auch der Boden unter den Füßen.
  ground.position.y = GROUND_TOP - GROUND_THICKNESS / 2;
  ground.receiveShadow = true;
  return markBackdrop(ground);
}

/**
 * **Wie groß ein Feld des Schachbretts ist**, in Metern.
 *
 * Ein Meter, und zwar derselbe Meter, in dem gebaut wird (`nav/navTile.TILE`).
 * Draußen sieht man damit dieselbe Einteilung wie drinnen: Wer eine Wand
 * setzen will, zählt Felder, und die Felder stimmen.
 */
export const CHECKER_TILE = 1;

/**
 * Das Feld daneben — eine Spur heller als die Grundfarbe.
 *
 * Damit bekommt **jede** Welt ihr Schachbrett, ohne eine zweite Farbe angeben
 * zu müssen: Der Hof bleibt ein Hof, der Hangar ein Hangar. Wer es wie in
 * Portal will (grau und weiß), gibt `checker` an.
 */
function mixed(color: number): number {
  const lift = (shift: number): number => {
    const channel = (color >> shift) & 0xff;
    return Math.min(255, Math.round(channel + (255 - channel) * 0.18)) << shift;
  };
  return lift(16) | lift(8) | lift(0);
}

/**
 * **Ein Schachbrett als Textur**, fertig zum Kacheln — wie oft, sagt der, der
 * sie bekommt (`repeat`).
 *
 * Sie steht als eigener Handgriff da, seit es einen **zweiten** Boden mit
 * Schachbrett gibt: den Küchenboden der Testwelt
 * (`worlds/test/zones/kitchenFloor.ts`), mit halben Feldern und eigenen Farben.
 * Der Zeichner darunter (`gridCanvas`) war nie das Schwierige — die vier
 * Einstellungen darum herum sind es, und jede davon ist ein Fehler, den man
 * erst in der Brille sieht:
 *
 * - **`SRGBColorSpace`**, sonst kommen die Farben zu hell heraus: Eine
 *   Leinwand trägt sRGB-Werte, und ein Renderer, dem das niemand sagt, rechnet
 *   sie ein zweites Mal hell.
 * - **`RepeatWrapping`** auf beiden Achsen, denn genau dafür sind es zwei mal
 *   zwei Felder: Ein Schachbrett setzt sich beim Kacheln nur fort, wenn beide
 *   Sorten Felder an jeder Kante liegen.
 * - **Mipmaps**, und die gibt es hier geschenkt: Die Leinwand ist 256 × 256
 *   Bildpunkte groß, also eine Zweierpotenz, und three.js baut die Stufen
 *   selbst. Ohne sie flimmert jedes Raster, sobald ein Feld kleiner wird als
 *   ein Bildpunkt.
 * - **`anisotropy`**, weil beide Böden flach unter einer schrägen Kamera
 *   liegen (55°, `core/topDownPose.ts`). Genau dort holt sich die
 *   Mipmap-Stufe ihre Unschärfe: Der Boden wäre in der Ferne matschig, lange
 *   bevor er dort klein ist.
 */
export function checkerTexture(color: number, line: number, checker: number): THREE.CanvasTexture {
  const texture = new THREE.CanvasTexture(gridCanvas(color, line, checker));
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.anisotropy = 8;
  return texture;
}

/**
 * **Zwei mal zwei Felder eines Schachbretts**, mit einer Linie um jedes.
 *
 * Ein Schachbrett und nicht mehr eine einzelne Fläche: Eine große einfarbige
 * Ebene mit einem Netz darauf ist in der Brille kaum von Nebel zu
 * unterscheiden — und ein Raster, dessen Felder man nicht **zählen** kann,
 * sagt einem nicht, wie weit man gelaufen ist. Zwei abwechselnde Töne sagen es.
 * Das Vorbild sind die Bodenplatten in Portal, und es ist dasselbe Vorbild,
 * aus dem die Portalflächen dieses Projekts kommen.
 */
function gridCanvas(color: number, line: number, checker: number): HTMLCanvasElement {
  const cell = 128;
  const canvas = document.createElement('canvas');
  canvas.width = cell * 2;
  canvas.height = cell * 2;
  const ctx = canvas.getContext('2d')!;
  const hex = (value: number): string => `#${value.toString(16).padStart(6, '0')}`;
  ctx.fillStyle = hex(color);
  ctx.fillRect(0, 0, cell * 2, cell * 2);
  ctx.fillStyle = hex(checker);
  ctx.fillRect(cell, 0, cell, cell);
  ctx.fillRect(0, cell, cell, cell);
  ctx.strokeStyle = hex(line);
  ctx.globalAlpha = 0.22;
  ctx.lineWidth = 2;
  for (let x = 0; x < 2; x++) {
    for (let z = 0; z < 2; z++) ctx.strokeRect(x * cell + 1, z * cell + 1, cell - 2, cell - 2);
  }
  return canvas;
}
